<template>
  <section class="run-archive">
    <header class="page-header"><div><p class="eyebrow">RUN ARCHIVE · AUDIT TRAIL</p><h1>运行档案</h1><p class="subtitle">把素材处理、知识审核、研究运行、Agent 审批和内容发布放在一条可筛选的时间线上。</p></div><el-button :loading="loading" @click="load">刷新档案</el-button></header>
    <div class="summary-grid"><div><span>全部事件</span><strong>{{ tasks.length }}</strong><small>当前工作空间</small></div><div><span>待处理</span><strong>{{ pendingCount }}</strong><small>需要人工动作</small></div><div><span>运行中</span><strong>{{ runningCount }}</strong><small>正在后台执行</small></div><div><span>失败</span><strong>{{ failedCount }}</strong><small>可以从任务中心重试</small></div></div>
    <el-card shadow="never" class="filter-card"><div class="filter-row"><el-input v-model="keyword" clearable placeholder="搜索任务、素材或研究名称" /><el-select v-model="kindFilter" clearable placeholder="全部类型"><el-option v-for="item in kindOptions" :key="item.value" :label="item.label" :value="item.value" /></el-select><el-select v-model="statusFilter" clearable placeholder="全部状态"><el-option label="待处理" value="pending" /><el-option label="运行中" value="running" /><el-option label="已完成" value="completed" /><el-option label="已取消" value="cancelled" /><el-option label="失败" value="failed" /></el-select><el-button @click="resetFilters">重置</el-button></div></el-card>
    <el-card shadow="never" class="archive-card"><template #header><div class="card-heading"><div><span class="section-kicker">AUDIT TIMELINE</span><h2>任务时间线</h2></div><el-tag effect="plain">{{ filteredTasks.length }} 条记录</el-tag></div></template><div v-if="filteredTasks.length" class="timeline"><article v-for="task in filteredTasks" :key="task.id" class="timeline-item"><span class="timeline-dot" :class="`is-${task.status}`" /><div class="timeline-main"><div class="timeline-top"><div><el-tag size="small" :type="statusType(task.status)">{{ statusLabel(task.status) }}</el-tag><span class="kind-label">{{ kindLabel(task.kind) }}</span></div><time>{{ formatDate(task.created_at) }}</time></div><h3>{{ task.title }}</h3><p>{{ task.metadata?.error_message || task.metadata?.description || '该运行记录由工作台任务系统自动生成，可从对应模块继续处理。' }}</p><div class="timeline-actions"><span>优先级 {{ task.priority }}</span><el-button v-if="task.route" link type="primary" @click="openTask(task.route)">打开相关模块 <el-icon><ArrowRight /></el-icon></el-button></div></div></article></div><el-empty v-else description="暂无匹配的运行记录" :image-size="72" /></el-card>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ArrowRight } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { useRouter } from 'vue-router'
import { workbenchApi, type WorkbenchTask } from '@/api/workbench'
import { useWorkspaceStore } from '@/stores/workspace'

const router = useRouter(); const workspaceStore = useWorkspaceStore(); const tasks = ref<WorkbenchTask[]>([]); const loading = ref(false); const keyword = ref(''); const kindFilter = ref(''); const statusFilter = ref('')
const kindOptions = [{ value: 'asset', label: '素材处理' }, { value: 'knowledge_review', label: '知识审核' }, { value: 'agent_approval', label: 'Agent 审批' }, { value: 'content_review', label: '内容审核' }, { value: 'content_publish', label: '内容发布' }, { value: 'agent_run', label: 'Agent 运行' }, { value: 'research_run', label: '研究运行' }]
const pendingCount = computed(() => tasks.value.filter(item => ['pending','waiting_approval'].includes(item.status)).length); const runningCount = computed(() => tasks.value.filter(item => ['running','processing','queued'].includes(item.status)).length); const failedCount = computed(() => tasks.value.filter(item => ['failed','error'].includes(item.status)).length)
const filteredTasks = computed(() => tasks.value.filter(task => { const text = `${task.title} ${task.kind} ${JSON.stringify(task.metadata || {})}`.toLowerCase(); return (!keyword.value || text.includes(keyword.value.toLowerCase())) && (!kindFilter.value || task.kind === kindFilter.value) && (!statusFilter.value || task.status === statusFilter.value) }))
function formatDate(value?: string | null) { return value ? new Date(value).toLocaleString('zh-CN') : '最近更新' }
function kindLabel(kind: string) { return kindOptions.find(item => item.value === kind)?.label || kind }
function statusLabel(status: string) { return ({ pending: '待处理', waiting_approval: '待审批', running: '运行中', processing: '处理中', queued: '排队中', completed: '已完成', cancelled: '已取消', failed: '失败', error: '错误' } as Record<string,string>)[status] || status }
function statusType(status: string) { return ['failed','error'].includes(status) ? 'danger' : ['completed'].includes(status) ? 'success' : ['running','processing','queued'].includes(status) ? 'warning' : 'info' }
function resetFilters() { keyword.value = ''; kindFilter.value = ''; statusFilter.value = '' }
function openTask(route: string) { router.push(route).catch(() => ElMessage.info('对应模块暂不可用，请从侧边栏进入')) }
async function load() { const workspaceId = workspaceStore.currentWorkspaceId; if (!workspaceId) return; loading.value = true; try { tasks.value = (await workbenchApi.listTasks(workspaceId, 200, true)).items || [] } catch (error) { ElMessage.error(error instanceof Error ? error.message : '运行档案加载失败') } finally { loading.value = false } }
onMounted(async () => { await workspaceStore.fetchCurrentWorkspace(); await load() })
</script>

<style scoped lang="scss">
.run-archive{max-width:1440px;margin:0 auto}.page-header{display:flex;justify-content:space-between;align-items:flex-start;gap:24px;margin-bottom:22px}.eyebrow,.section-kicker{color:var(--el-color-primary);font-size:11px;font-weight:800;letter-spacing:.16em}.eyebrow{margin:0 0 8px}h1{margin:0 0 8px;font-family:Georgia,'Times New Roman',serif;font-size:clamp(32px,4vw,48px);letter-spacing:-.045em}.subtitle{max-width:720px;margin:0;color:var(--el-text-color-secondary);line-height:1.75}.summary-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:18px}.summary-grid>div,.filter-card,.archive-card{border:1px solid rgba(112,74,198,.13);border-radius:18px;background:linear-gradient(145deg,rgba(255,255,255,.96),rgba(249,247,255,.9));box-shadow:0 12px 30px rgba(79,51,133,.05)}.summary-grid>div{display:flex;flex-direction:column;gap:6px;padding:18px 20px}.summary-grid span,.summary-grid small,.timeline-top time,.timeline-actions span,.timeline-main p{color:var(--el-text-color-secondary)}.summary-grid strong{font-family:Georgia,'Times New Roman',serif;font-size:30px;color:var(--el-color-primary)}.filter-card{margin-bottom:18px}.filter-card :deep(.el-card__body){padding:14px}.filter-row{display:flex;gap:10px}.filter-row .el-input{flex:1}.filter-row .el-select{width:170px}.archive-card{min-height:300px}.card-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}.card-heading h2{margin:5px 0 0;font-size:20px}.timeline{position:relative;display:grid;gap:0;padding-left:14px}.timeline:before{content:'';position:absolute;top:10px;bottom:10px;left:22px;width:1px;background:rgba(112,74,198,.16)}.timeline-item{position:relative;display:flex;gap:18px;padding:12px 0 16px}.timeline-dot{position:relative;z-index:1;width:17px;height:17px;flex:0 0 17px;margin-top:4px;border:4px solid #f8f5ff;border-radius:50%;background:#8e71d1;box-shadow:0 0 0 1px rgba(112,74,198,.25)}.timeline-dot.is-completed{background:#4f9b72}.timeline-dot.is-failed{background:#d66b76}.timeline-dot.is-running,.timeline-dot.is-processing{background:#d59a42}.timeline-main{flex:1;padding:14px 16px;border:1px solid rgba(112,74,198,.1);border-radius:14px;background:rgba(255,255,255,.68)}.timeline-top,.timeline-actions{display:flex;justify-content:space-between;align-items:center;gap:10px}.timeline-top>div{display:flex;align-items:center;gap:10px}.kind-label{color:var(--el-text-color-secondary);font-size:12px}.timeline-main h3{margin:11px 0 5px;font-size:16px}.timeline-main p{margin:0 0 12px;line-height:1.6}.timeline-actions{border-top:1px solid rgba(112,74,198,.08);padding-top:10px}
@media(max-width:900px){.summary-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.filter-row{flex-wrap:wrap}.filter-row .el-input{min-width:100%}}@media(max-width:620px){.page-header{flex-direction:column}.filter-row .el-select{width:100%}}
</style>
